INSERT INTO "MascotDialogue" ("id", "key", "context", "text", "sortOrder", "updatedAt") VALUES
('mascot-pet-needs-care-01', 'pet-needs-care-01', 'PET_NEEDS_CARE', '我的小肚子和水杯都空啦，先照顾我一下吧。', 510, CURRENT_TIMESTAMP),
('mascot-pet-needs-care-02', 'pet-needs-care-02', 'PET_NEEDS_CARE', '先吃点东西、喝口水，我就又有精神啦。', 520, CURRENT_TIMESTAMP),
('mascot-pet-needs-care-03', 'pet-needs-care-03', 'PET_NEEDS_CARE', '今天想陪你很久，能先帮我补充能量吗？', 530, CURRENT_TIMESTAMP),
('mascot-pet-needs-care-04', 'pet-needs-care-04', 'PET_NEEDS_CARE', '肚子咕咕叫，嘴巴也有点干，我需要你的照顾。', 540, CURRENT_TIMESTAMP),
('mascot-pet-hungry-01', 'pet-hungry-01', 'PET_HUNGRY', '肚子在咕咕唱歌，能给我一点点心吗？', 610, CURRENT_TIMESTAMP),
('mascot-pet-hungry-02', 'pet-hungry-02', 'PET_HUNGRY', '我闻到点心的香味啦，肚子也想尝一口。', 620, CURRENT_TIMESTAMP),
('mascot-pet-hungry-03', 'pet-hungry-03', 'PET_HUNGRY', '补充一点能量，我就能元气满满地陪你。', 630, CURRENT_TIMESTAMP),
('mascot-pet-hungry-04', 'pet-hungry-04', 'PET_HUNGRY', '今天的点心会是什么味道呢？我有点饿啦。', 640, CURRENT_TIMESTAMP),
('mascot-pet-thirsty-01', 'pet-thirsty-01', 'PET_THIRSTY', '跑了这么久，我想喝一口清凉的水。', 710, CURRENT_TIMESTAMP),
('mascot-pet-thirsty-02', 'pet-thirsty-02', 'PET_THIRSTY', '小水杯空啦，能帮我加一点水吗？', 720, CURRENT_TIMESTAMP),
('mascot-pet-thirsty-03', 'pet-thirsty-03', 'PET_THIRSTY', '喝饱水以后，我会更有精神陪你玩。', 730, CURRENT_TIMESTAMP),
('mascot-pet-thirsty-04', 'pet-thirsty-04', 'PET_THIRSTY', '嘴巴有一点干，我想听见咕嘟咕嘟的声音。', 740, CURRENT_TIMESTAMP),
('mascot-pet-task-start-01', 'pet-task-start-01', 'PET_TASK_START', '新的一天开始啦，做完任务再回来陪我玩吧。', 810, CURRENT_TIMESTAMP),
('mascot-pet-task-start-02', 'pet-task-start-02', 'PET_TASK_START', '今天会学到什么呢？我在小屋等你的好消息。', 820, CURRENT_TIMESTAMP),
('mascot-pet-task-start-03', 'pet-task-start-03', 'PET_TASK_START', '选一个想做的任务，勇敢迈出第一步吧。', 830, CURRENT_TIMESTAMP),
('mascot-pet-task-start-04', 'pet-task-start-04', 'PET_TASK_START', '不用着急，认真开始就已经很棒啦。', 840, CURRENT_TIMESTAMP),
('mascot-pet-task-progress-01', 'pet-task-progress-01', 'PET_TASK_PROGRESS', '欢迎回来！完成一点、休息一下，节奏刚刚好。', 910, CURRENT_TIMESTAMP),
('mascot-pet-task-progress-02', 'pet-task-progress-02', 'PET_TASK_PROGRESS', '你认真做事的时候，我也在小屋里为你加油。', 920, CURRENT_TIMESTAMP),
('mascot-pet-task-progress-03', 'pet-task-progress-03', 'PET_TASK_PROGRESS', '已经向前走了一段，接下来也按自己的节奏来。', 930, CURRENT_TIMESTAMP),
('mascot-pet-task-progress-04', 'pet-task-progress-04', 'PET_TASK_PROGRESS', '累了就看看我，休息好再继续出发。', 940, CURRENT_TIMESTAMP),
('mascot-pet-task-progress-05', 'pet-task-progress-05', 'PET_TASK_PROGRESS', '每一次认真尝试，都让今天变得更精彩。', 950, CURRENT_TIMESTAMP),
('mascot-pet-task-complete-01', 'pet-task-complete-01', 'PET_TASK_COMPLETE', '今天辛苦啦，现在我们可以安心玩一会儿。', 1010, CURRENT_TIMESTAMP),
('mascot-pet-task-complete-02', 'pet-task-complete-02', 'PET_TASK_COMPLETE', '你把今天的事情做好啦，我真为你开心。', 1020, CURRENT_TIMESTAMP),
('mascot-pet-task-complete-03', 'pet-task-complete-03', 'PET_TASK_COMPLETE', '今天的探险圆满结束，来小屋放松一下吧。', 1030, CURRENT_TIMESTAMP),
('mascot-pet-task-complete-04', 'pet-task-complete-04', 'PET_TASK_COMPLETE', '认真又坚持的你，今天闪闪发光。', 1040, CURRENT_TIMESTAMP),
('mascot-pet-task-complete-05', 'pet-task-complete-05', 'PET_TASK_COMPLETE', '所有任务都完成啦，接下来想和我做什么呢？', 1050, CURRENT_TIMESTAMP),
('mascot-pet-relax-01', 'pet-relax-01', 'PET_RELAX', '今天没有新任务，我们一起轻松玩一会儿吧。', 1110, CURRENT_TIMESTAMP),
('mascot-pet-relax-02', 'pet-relax-02', 'PET_RELAX', '难得的悠闲时光，想带我去哪里看看呢？', 1120, CURRENT_TIMESTAMP),
('mascot-pet-relax-03', 'pet-relax-03', 'PET_RELAX', '今天可以慢慢来，陪我在小屋里待一会儿吧。', 1130, CURRENT_TIMESTAMP),
('mascot-pet-relax-04', 'pet-relax-04', 'PET_RELAX', '没有任务的日子，也可以发现很多小快乐。', 1140, CURRENT_TIMESTAMP),
('mascot-pet-general-01', 'pet-general-01', 'PET_GENERAL', '见到你真开心，来摸摸我吧。', 1210, CURRENT_TIMESTAMP),
('mascot-pet-general-02', 'pet-general-02', 'PET_GENERAL', '我一直在小屋里等你回来。', 1220, CURRENT_TIMESTAMP),
('mascot-pet-general-03', 'pet-general-03', 'PET_GENERAL', '今天也要记得给自己一个大大的微笑。', 1230, CURRENT_TIMESTAMP),
('mascot-pet-general-04', 'pet-general-04', 'PET_GENERAL', '和你待在一起，就是我最喜欢的时光。', 1240, CURRENT_TIMESTAMP)
